// Copies the scenario PDFs (tender, drawing plot) generated by WS2 into public/demo/docs so the
// citation viewer works from Hosting with the backend down. Runs before `vite` and `vite build`.
import { copyFileSync, existsSync, mkdirSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const src = join(here, '../../../scenarios/hall_a/out')
const dest = join(here, '../public/demo/docs')

if (!existsSync(src)) {
  console.warn(`[sync-demo-docs] ${src} not found yet (WS2 generates it); citations will show "could not load".`)
  process.exit(0)
}
mkdirSync(dest, { recursive: true })
const pdfs = readdirSync(src).filter((f) => f.endsWith('.pdf'))
for (const f of pdfs) copyFileSync(join(src, f), join(dest, f))
console.log(`[sync-demo-docs] copied ${pdfs.length} PDF(s) to public/demo/docs`)
